begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
create function pg_temp.id(n integer)returns uuid language sql immutable as $$select('d1600000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid$$;
insert into auth.users(id,email,email_confirmed_at)values(pg_temp.id(1),'synthetic-account-a@example.test',now()),(pg_temp.id(2),'synthetic-account-b@example.test',now());
insert into auth.sessions(id,user_id,created_at)values(pg_temp.id(11),pg_temp.id(1),clock_timestamp()),(pg_temp.id(12),pg_temp.id(2),clock_timestamp());
insert into public.doctor_profiles(user_id,display_name)values(pg_temp.id(1),'Professional A');
insert into public.practices(id,owner_user_id,name)values(pg_temp.id(21),pg_temp.id(1),'Practice A');
insert into public.memberships(id,practice_id,user_id,capabilities)values(pg_temp.id(31),pg_temp.id(21),pg_temp.id(2),array['patients.read']);
create function pg_temp.claim(n integer)returns text language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.id(n),'session_id',pg_temp.id(n+10),'role','authenticated')::text,true)$$;
create function pg_temp.save(name text,phone text,pref boolean,version integer,key integer)returns jsonb language sql as $$select public.doctor_update_account_settings(name,phone,pref,version,pg_temp.id(key))$$;
set local role authenticated;select pg_temp.claim(1);
select is(public.doctor_account_settings()->>'version','0','C01 missing personal profile is an honest empty account');
select is(public.doctor_account_settings()->>'in_app_confirmations','false','C03 communication preference defaults off');
select is(pg_temp.save('Personal A','+12025550123',true,0,41)->>'version','1','C01 own personal profile updates');
select is(pg_temp.save('Personal A','+12025550123',true,0,41)->>'version','1','same intent replays once');
select throws_ok($$select pg_temp.save('Other','+12025550123',true,0,41)$$,'40001','DOCTOR_COMMAND_CONFLICT','changed retry intent is rejected');
select throws_ok($$select pg_temp.save('Stale','',false,0,42)$$,'40001','DOCTOR_ACCOUNT_CONFLICT','stale editor cannot overwrite account');
select is((select display_name from public.doctor_profiles where user_id=pg_temp.id(1)),'Professional A','C01 personal name does not alter professional profile');
select throws_ok($$update public.account_profiles set personal_name='Direct'$$,'42501',null,'direct writes denied');
select throws_ok($$select * from doctor_private.account_events$$,'42501',null,'audit metadata is not a public data API');
select throws_ok($$update doctor_private.account_security_policy set contact_reauthentication_seconds=3600$$,'42501',null,'clients cannot extend freshness policy');
select pg_temp.claim(2);
select is((select count(*)::integer from public.account_profiles),0,'C01 another account cannot read personal data');
select is(public.doctor_account_settings()->>'in_app_confirmations','false','C03 other account preference remains off');
select is(pg_temp.save('Personal B','',false,0,43)->>'personal_name','Personal B','C01 secretary has an independent account profile');
select is((select capabilities from public.memberships where id=pg_temp.id(31)),array['patients.read'],'C01 account edits cannot grant membership capabilities');
reset role;
select is((select count(*)::integer from doctor_private.account_events),2,'replay and rejected commands emit no extra audit');
update public.doctor_profiles set display_name='Professional revised'where user_id=pg_temp.id(1);
select is((select personal_name from public.account_profiles where user_id=pg_temp.id(1)),'Personal A','C01 professional update does not alter personal name');
update auth.sessions set created_at=clock_timestamp()-interval '16 minutes'where id=pg_temp.id(11);
set local role authenticated;select pg_temp.claim(1);
select is(public.doctor_account_settings()->>'can_change_contact','false','C02 expired provider sign-in cannot edit sensitive contact');
select throws_ok($$select pg_temp.save('Personal A','+12025550124',true,1,44)$$,'28000','DOCTOR_REAUTHENTICATION_REQUIRED','C02 expired contact change denied');
select throws_ok($$select pg_temp.save('Personal A','',true,1,45)$$,'28000','DOCTOR_REAUTHENTICATION_REQUIRED','clearing contact also requires freshness');
select throws_ok($$select pg_temp.save('Personal A','+12025550123',true,0,41)$$,'28000','DOCTOR_REAUTHENTICATION_REQUIRED','sensitive receipt replay cannot bypass freshness');
select is(pg_temp.save('Personal revised','+12025550123',false,1,46)->>'version','2','non-sensitive personal edit works with an active older session');
reset role;
select is((select count(*)::integer from doctor_private.account_events where actor_user_id=pg_temp.id(1)),2,'denied contact writes add no audit');
select is((select count(*)::integer from doctor_private.command_receipts where command_key in(pg_temp.id(44),pg_temp.id(45))),0,'denied changes leave no receipts');
select is((select contact_phone from public.account_profiles where user_id=pg_temp.id(1)),'+12025550123','denied changes preserve stored contact');
-- SQL scaffold only: actual GoTrue session issuance is checked independently.
insert into auth.sessions(id,user_id,created_at)values(pg_temp.id(13),pg_temp.id(1),clock_timestamp());
set local role authenticated;
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.id(1),'session_id',pg_temp.id(13),'role','authenticated')::text,true);
select is(pg_temp.save('Personal revised','+12025550124',false,2,47)->>'version','3','fresh provider session admits sensitive update');
select throws_ok($$select pg_temp.save('Personal A','+12025550123',true,0,41)$$,'40001','DOCTOR_COMMAND_CONFLICT','receipt keys are bound to the issuing SID');
select throws_ok($$select pg_temp.save('Bad','123',false,3,48)$$,'22023','DOCTOR_INVALID_ACCOUNT_SETTINGS','invalid phone format denied');
select throws_ok($$select pg_temp.save(E'Bad\nname','',false,3,49)$$,'22023','DOCTOR_INVALID_ACCOUNT_SETTINGS','control characters denied');
reset role;delete from auth.sessions where id=pg_temp.id(13);
set local role authenticated;
select throws_ok($$select public.doctor_account_settings()$$,'42501','DOCTOR_AUTH_REQUIRED','revoked SID cannot read settings');
select throws_ok($$select pg_temp.save('Revoked','',false,3,50)$$,'42501','DOCTOR_AUTH_REQUIRED','revoked SID cannot write settings');
select pg_temp.claim(2);
select is(public.doctor_account_settings()->>'personal_name','Personal B','independent B session remains usable after A revocation');
reset role;
select is((select count(*)::integer from doctor_private.account_events where actor_user_id=pg_temp.id(1)),3,'only successful account versions are audited');
select is((select actor_session_id from doctor_private.account_events where actor_user_id=pg_temp.id(1)and account_version=3),pg_temp.id(13),'audit attributes exact provider session');
set local role anon;
select throws_ok($$select public.doctor_account_settings()$$,'42501',null,'anonymous account read denied');
select throws_ok($$select pg_temp.save('Anonymous','',false,0,51)$$,'42501',null,'anonymous write denied');
reset role;
select * from finish();rollback;
